#[allow(unused_variables)] fn ability_0_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); ((q.history().this_turn().iter().filter_map(|r: &Record| -> Option<Fired> { let event = &r.event; if let Event::SpellCast { spell, player, .. } = event { let id = *spell; let subject = Target::Object(id); let data = [u32::from(player.0), u32::MAX]; if Some(asker.controller) == Some(*player) && (q.chars(id).is(CardType::Artifact) || q.chars(id).supertypes.legendary || q.chars(id).has_subtype(q.words(asker.source).subtype(Subtype::Saga))) { return Some(Fired { subject, data }); } }  None }).count() as i64) >= (1i64)) && (source == affected) }
#[allow(unused_variables)] fn ability_0_0_0_keyword(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); if (q.history().this_turn().iter().filter_map(|r: &Record| -> Option<Fired> { let event = &r.event; if let Event::SpellCast { spell, player, .. } = event { let id = *spell; let subject = Target::Object(id); let data = [u32::from(player.0), u32::MAX]; if Some(asker.controller) == Some(*player) && (q.chars(id).is(CardType::Artifact) || q.chars(id).supertypes.legendary || q.chars(id).has_subtype(q.words(asker.source).subtype(Subtype::Saga))) { return Some(Fired { subject, data }); } }  None }).count() as i64) >= (1i64) { chars.keywords = chars.keywords.with(Keyword::CantBeBlocked); } }

